//! Source-measured STORE brand and rifle contours from img-09-store.png.
//! Grid points are native pixel-edge coordinates, decoded to 1600x900 design units.
//! Each ring start uses bit 15; all shapes stay editable vectors, never a raster.
use crate::palette::rgb;
use crate::style::{Ink, Prim, Seg};

const fn decode<const N: usize>(points: &[(u16, u16); N], origin_x: f32, origin_y: f32) -> [Seg; N] {
    let mut out = [Seg::Line(0.0, 0.0); N];
    let mut i = 0;
    while i < N {
        let (x, y) = points[i];
        let px = (x & 0x7fff) as f32 / 2.4 - origin_x;
        let py = y as f32 / 2.4 - origin_y;
        out[i] = if x & 0x8000 != 0 { Seg::Move(px, py) } else { Seg::Line(px, py) };
        i += 1;
    }
    out
}

